"""Correct plate defects with original poses and quiet object positioning."""
import json
import prepare as g
import produce as p
IDENTITY='Continuous painted studio pose study of the supplied original slender blue-and-ivory masked mourner. Exactly two arms, two legs, one rigid bronze instrument with three pale blue glass cylinders, one lower hanging lantern, original belt scrolls and ragged blue cloth. The original near hand retains its grip on the shaft. All original equipment retains its shape, painted brightness and color. '
PLATE=' Only the supplied painted body, cloth and held instrument visible against continuous featureless flat magenta RGB255,0,255. Fixed camera and body scale. No scenery, stage, rings, particles, glow, lighting transitions or changes in backdrop color. Every staff tip and robe ribbon stays inside generous canvas margins. Planted boots remain on y576. '
specs=[('defend',[0,9,10],[[20,1],[45,2],[72,2],[100,2]],2,2026108210,'The free far forearm rises above the brow while both knees bend into the supplied compact crouch. The near hand inclines the single rigid bronze instrument across the upper body as shown. The free hand rests above the head, elbow bent. Both boots stay firmly planted. Hold the supplied final crouched position, with cloth settling. '),('cast',[0,11],[[25,1],[50,1],[72,1],[100,0]],0,2026108211,'The free far hand slowly rises inward from the waist to beside the face, elbow bending close to the torso. The masked head bows toward that palm. The near hand holds the same upright rigid instrument throughout. Then the head lifts and free hand slowly lowers to its initial position. All movement comes from shoulders, elbow, wrist and neck; cloth follows gently. ') ]
for clip,indices,guides,last,seed,action in specs:
 out=p.SOURCE_DIR/(clip+'_h3_v2');out.mkdir(exist_ok=True);assert not (out/'submitted.json').exists()
 c=dict(unit_id=g.UID,clip=clip,canvas=[960,640],anchor=[480,576],scale=.5,key_rgb=[255,0,255],seed=seed,references=[g.reference(i) for i in indices],guides=guides,last=last,prompt=(IDENTITY+action+PLATE).strip(),tiled_decode=dict(tile_size=512,overlap=64,temporal_size=16,temporal_overlap=4))
 p.write(out/'config.json',c);p.prepare(out,c);p.verify(out,c)
r=json.loads((p.SOURCE_DIR/'rejected_takes.json').read_bytes());r['takes'] += [dict(take='defend_h3_v1',status='rejected',defect='Dark blue source plate weakens semantic opacity of robe and legs during the actual crouch. Source motion is genuine but extraction is not acceptable.',correction='Quiet original-pose studio sequence with four magenta guard guides.'),dict(take='cast_h3_v1',status='rejected',defect='Green-cyan plate is insufficiently separated from pale-blue saltglass. Enclosed semantic recovery restores some pixels but glass contour gaps remain. Original RGB, semantic masks and recovery preserved.',correction='Quiet original-pose studio gesture with four magenta guides and no spell phrasing.')];p.write(p.SOURCE_DIR/'rejected_takes.json',r)
d=json.loads((p.SOURCE_DIR/'delivery.json').read_bytes());d['takes']=[x.replace('defend_h3_v1','defend_h3_v2').replace('cast_h3_v1','cast_h3_v2') for x in d['takes']];p.write(p.SOURCE_DIR/'delivery.json',d)
